from urllib.parse import urlparse, parse_qs, unquote

def parse_query_string(query):
    """
    Parse a URL query string into a dict mapping each key to a list of decoded values.
    Ignore a leading ?. Use urllib.parse semantics for percent decoding and blank values.
    """
    if not query:
        return {}

    # Remove leading '?' if present
    if query.startswith('?'):
        query = query[1:]

    if not query:
        return {}

    # parse_qs handles percent decoding and returns a dict mapping keys to lists of values.
    # It correctly handles empty values (e.g., "a=&b" -> {'a': [''], 'b': ['']})
    # and multiple values for the same key (e.g., "a=1&a=2" -> {'a': ['1', '2']}).
    parsed_qs = parse_qs(query)

    # parse_qs already uses unquote semantics internally, which matches the requirement.
    return parsed_qs

def parse_env_lines(text):
    env_vars = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        if '=' in line:
            key, value = line.split('=', 1)
            env_vars[key.strip()] = value.strip()

    return env_vars

def parse_semver(value):
    """
    Parse a semantic version string MAJOR.MINOR.PATCH with an optional leading v.
    Return a tuple of three integers. Reject missing parts, non-integers, or negative numbers with ValueError.
    """
    if not isinstance(value, str):
        raise ValueError("Input must be a string.")

    # Remove optional leading 'v'
    version_str = value
    if version_str.startswith('v'):
        version_str = version_str[1:]

    parts = version_str.split('.')

    if len(parts) != 3:
        raise ValueError("Semantic version must have MAJOR.MINOR.PATCH format.")

    try:
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])
    except ValueError:
        # This catches cases where parts[i] cannot be converted to int (e.g., "1.a.2")
        raise ValueError("All version components must be integers.")

    # Check for negative numbers
    if major < 0 or minor < 0 or patch < 0:
        raise ValueError("Version components cannot be negative.")

    return (major, minor, patch)

def parse_bool(value):
    if not isinstance(value, str):
        raise ValueError(f"Input must be a string, got {type(value).__name__}")

    normalized_value = value.strip().lower()

    true_values = {'true', 'yes', 'y', '1', 'on'}
    false_values = {'false', 'no', 'n', '0', 'off'}

    if normalized_value in true_values:
        return True
    elif normalized_value in false_values:
        return False
    else:
        raise ValueError(f"Cannot parse boolean from '{value}'")

