def group_count(rows, key):
    counts = {}
    for row in rows:
        value = row.get(key)
        if value is None:
            value = None

        if value not in counts:
            counts[value] = 0
        counts[value] += 1
    return counts

def group_sum(rows, key, value_key):
    result = {}
    for row in rows:
        group = row.get(key)
        if group not in result:
            result[group] = 0

        value = row.get(value_key)
        if isinstance(value, (int, float)):
            result[group] += value
        # If value is missing or not numeric, it contributes 0, which is handled by not adding anything.
        # The requirement "Missing value keys count as 0" is satisfied by the conditional addition.

    return result

def project_fields(rows, fields):
    projected_rows = []
    for row in rows:
        new_row = {}
        for field in fields:
            if field in row:
                new_row[field] = row[field]
        projected_rows.append(new_row)
    return projected_rows

