def median(values):
    if not values:
        raise ValueError("Input iterable cannot be empty")

    sorted_values = sorted(values)
    n = len(sorted_values)

    if n % 2 == 1:
        # Odd number of elements, return the middle one
        return sorted_values[n // 2]
    else:
        # Even number of elements, return the average of the two middle ones
        mid1 = sorted_values[n // 2 - 1]
        mid2 = sorted_values[n // 2]
        return (mid1 + mid2) / 2.0

def percent_change(old, new):
    if old == 0:
        raise ValueError("old cannot be zero")
    return ((new - old) / old) * 100

def clamp_numbers(values, low, high):
    if low > high:
        raise ValueError("low cannot be greater than high")

    return [max(low, min(high, v)) for v in values]

def moving_average(values, size):
    if size <= 0:
        raise ValueError("size must be positive")

    if not values or size > len(values):
        return []

    averages = []
    for i in range(len(values) - size + 1):
        window = values[i:i+size]
        average = sum(window) / size
        averages.append(average)

    return averages

def histogram_bins(values, bin_size):
    if bin_size <= 0:
        raise ValueError("bin_size must be greater than 0")

    counts = {}
    for value in values:
        # Calculate the bin start. Integer division by bin_size gives the index,
        # and multiplying by bin_size gives the start of the bin.
        # For bin_size 10:
        # 0..9 -> 0 // 10 * 10 = 0
        # 10..19 -> 10 // 10 * 10 = 10
        # -1..8 -> -1 // 10 * 10 = -10 (Python's floor division handles negatives correctly)
        bin_start = (value // bin_size) * bin_size

        if bin_start in counts:
            counts[bin_start] += 1
        else:
            counts[bin_start] = 1

    return counts

