from collections import deque

def shortest_path_unweighted(graph, start, goal):
    if start == goal:
        return [start]

    queue = deque([(start, [start])])
    visited = {start}

    while queue:
        current_node, path = queue.popleft()

        if current_node in graph:
            # Iterate over neighbors in the order they appear in the adjacency list
            for neighbor in graph[current_node]:
                if neighbor == goal:
                    return path + [neighbor]

                if neighbor not in visited:
                    visited.add(neighbor)
                    new_path = path + [neighbor]
                    queue.append((neighbor, new_path))

    return None

def has_cycle_directed(graph):
    """
    Checks if a directed graph has a cycle.

    The graph is represented as a dictionary where keys are nodes and values 
    are lists of neighbors (outgoing edges).
    """

    # State tracking for DFS
    # 0: unvisited (white)
    # 1: visiting (gray - currently in the recursion stack)
    # 2: visited (black - finished processing)
    state = {node: 0 for node in graph}

    # Ensure all nodes mentioned as neighbors are also in the state map, 
    # even if they have no outgoing edges listed in the input graph keys.
    for neighbors in graph.values():
        for neighbor in neighbors:
            if neighbor not in state:
                state[neighbor] = 0

    def dfs(node):
        # Mark current node as visiting (gray)
        state[node] = 1

        # Explore neighbors
        if node in graph:
            for neighbor in graph[node]:
                if state.get(neighbor) == 1:
                    # Found a back edge to a node currently in the recursion stack (gray)
                    return True

                if state.get(neighbor) == 0:
                    # Unvisited, recurse
                    if dfs(neighbor):
                        return True

        # Finished processing this node and all its descendants (black)
        state[node] = 2
        return False

    # Iterate over all nodes to handle disconnected components
    for node in state:
        if state[node] == 0:
            if dfs(node):
                return True

    return False

def reverse_adjacency(graph):
    """
    Reverses the adjacency list representation of a graph.

    Args:
        graph: A dictionary where keys are nodes and values are lists of neighbors (outgoing edges).

    Returns:
        A dictionary where each node maps to the sorted list of incoming neighbors.
        Includes nodes that only appear as neighbors.
    """
    reversed_graph = {}

    # 1. Initialize all nodes (both sources and destinations) in the reversed graph
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        all_nodes.update(neighbors)

    for node in all_nodes:
        reversed_graph[node] = []

    # 2. Populate the reversed edges
    for u, neighbors in graph.items():
        for v in neighbors:
            # Edge u -> v in original graph means v -> u in reversed graph
            if v in reversed_graph:
                reversed_graph[v].append(u)
            # This case should ideally not happen if initialization was correct, 
            # but it's safe to handle.
            else:
                reversed_graph[v] = [u]

    # 3. Sort the lists of incoming neighbors
    for node in reversed_graph:
        reversed_graph[node].sort()

    return reversed_graph

