def json_get_path(data, path, default=None):
    """
    Return a nested value from dict/list data using a dot-separated path.
    Numeric path parts index lists. Return default if any part is missing or invalid.
    """
    if not path:
        return data

    keys = path.split('.')
    current = data

    for key in keys:
        if isinstance(current, dict):
            if key in current:
                current = current[key]
            else:
                return default
        elif isinstance(current, list):
            try:
                index = int(key)
                if 0 <= index < len(current):
                    current = current[index]
                else:
                    return default
            except ValueError:
                # Key is not a valid integer index for a list
                return default
        else:
            # Current object is neither dict nor list, cannot traverse further
            return default

    return current

import copy

def json_set_path(data, path, value):
    """
    Returns a deep-copied dict with value assigned at a dot-separated object path.
    Creates missing dicts as needed. Does not mutate the input.
    """
    new_data = copy.deepcopy(data)
    keys = path.split('.')
    current = new_data

    for i, key in enumerate(keys):
        is_last = (i == len(keys) - 1)

        if is_last:
            current[key] = value
        else:
            if key not in current or not isinstance(current[key], dict):
                current[key] = {}
            current = current[key]

    return new_data

def flatten_dict(data, sep='.'):
    items = []

    def _flatten(x, prefix=''):
        if isinstance(x, dict):
            for k, v in x.items():
                new_key = f"{prefix}{sep}{k}" if prefix else k
                _flatten(v, new_key)
        else:
            items.append((prefix, x))

    _flatten(data)
    return dict(items)

