import os

def extension_counts(paths):
    counts = {}
    for path in paths:
        # os.path.splitext splits the path into (root, extension)
        # The extension includes the leading dot, e.g., ".txt"
        _, ext = os.path.splitext(path)

        # Remove the leading dot and convert to lowercase
        if ext:
            ext_name = ext[1:].lower()
        else:
            # Use an empty string for paths with no suffix
            ext_name = ""

        counts[ext_name] = counts.get(ext_name, 0) + 1
    return counts

