def validate_parentheses(text):
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}
    opening_brackets = set("([{")
    closing_brackets = set(")]}")

    for char in text:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack:
                return False
            top_element = stack.pop()
            if mapping[char] != top_element:
                return False
        # Ignore other characters

    return not stack

def run_length_encode(items):
    if not items:
        return []

    encoded_list = []
    current_value = items[0]
    current_count = 0

    for item in items:
        if item == current_value:
            current_count += 1
        else:
            encoded_list.append((current_value, current_count))
            current_value = item
            current_count = 1

    # Append the last sequence
    encoded_list.append((current_value, current_count))
    return encoded_list

def run_length_decode(pairs):
    decoded_list = []
    for value, count in pairs:
        if count < 0:
            raise ValueError("Count cannot be negative")
        decoded_list.extend([value] * count)
    return decoded_list

def expand_ranges(ranges):
    expanded_list = []
    for start, end in ranges:
        if start > end:
            raise ValueError("Start of range cannot be greater than end of range.")
        for i in range(start, end + 1):
            expanded_list.append(i)
    return expanded_list

