def stable_partition(items, predicate):
    matching = []
    non_matching = []
    for item in items:
        if predicate(item):
            matching.append(item)
        else:
            non_matching.append(item)
    return (matching, non_matching)

def pairwise_deltas(values):
    if len(values) < 2:
        return []
    deltas = []
    for i in range(len(values) - 1):
        delta = values[i+1] - values[i]
        deltas.append(delta)
    return deltas
